class Solution {
    void mergeSort(int[] a) { sort(a, 0, a.length - 1, new int[a.length]); }
    void sort(int[] a, int l, int r, int[] tmp) {
        if (l >= r) return; int m = l + (r - l) / 2;
        sort(a, l, m, tmp); sort(a, m + 1, r, tmp);
        int i = l, j = m + 1, k = l;
        while (i <= m && j <= r) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
        while (i <= m) tmp[k++] = a[i++]; while (j <= r) tmp[k++] = a[j++];
        for (i = l; i <= r; i++) a[i] = tmp[i];
    }
}

