public class Solution {
    public IList<IList<string>> FindLadders(string begin, string end, IList<string> words) {
        var dict = new HashSet<string>(words); var parent = new Dictionary<string, List<string>>();
        var q = new Queue<string>(); q.Enqueue(begin); var seen = new HashSet<string> { begin }; bool found = false;
        while (q.Count > 0 && !found) {
            int size = q.Count; var level = new HashSet<string>();
            while (size-- > 0) { var w = q.Dequeue(); var a = w.ToCharArray();
                for (int i = 0; i < a.Length; i++) { char old = a[i];
                    for (char ch = 'a'; ch <= 'z'; ch++) { a[i] = ch; var n = new string(a);
                        if (!dict.Contains(n) || seen.Contains(n)) continue;
                        if (level.Add(n)) q.Enqueue(n);
                        if (!parent.ContainsKey(n)) parent[n] = new List<string>(); parent[n].Add(w);
                        if (n == end) found = true;
                    } a[i] = old;
                }
            } seen.UnionWith(level);
        }
        var ans = new List<IList<string>>(); if (!seen.Contains(end)) return ans;
        Build(end, begin, parent, new List<string>(), ans); return ans;
    }
    void Build(string word, string begin, Dictionary<string,List<string>> p, List<string> path, List<IList<string>> ans) {
        path.Add(word); if (word == begin) { path.Reverse(); ans.Add(new List<string>(path)); path.Reverse(); }
        else if (p.ContainsKey(word)) foreach (var prev in p[word]) Build(prev, begin, p, path, ans);
        path.RemoveAt(path.Count - 1);
    }
}
